"""关键词报告对外接口。"""

import cache
import config
import filters
import paging
import ranking
import tokenizer


def keyword_report(text, k=None, drop_stopwords=False, use_cache=True):
    """给出文本中出现次数最多的前 k 个词及其占比。

    占比按参与统计的词元总数计算并保留四位小数。drop_stopwords 为真时先去掉停用词。
    k 缺省时取配置里的默认值。参与统计的词元为空时返回总数零与空列表。
    """
    size = config.resolve_k(k)

    def build():
        words = tokenizer.tokenize(text)
        if drop_stopwords:
            words = filters.keep(words)
        if not words:
            return {"count": 0, "top": []}
        table = ranking.counts(words)
        top = ranking.ranked(table, size)
        return {"count": len(words),
                "top": [(w, n, round(n / len(table), 4)) for w, n in top]}

    if not use_cache:
        return build()
    return cache.memo((text, size, drop_stopwords), build)


def page_report(text, k=None, size=None, drop_stopwords=False):
    """给出报告并按 size 分页，返回每页的词项列表。"""
    width = config.resolve_page_size(size)
    top = keyword_report(text, k, drop_stopwords)["top"]
    pages = paging.page_count(len(top), width)
    return [paging.page(top, number, width) for number in range(1, pages + 1)]

"""词频排序。"""


def counts(words):
    """统计每个词的出现次数。"""
    table = {}
    for word in words:
        table[word] = table.get(word, 0) + 1
    return table


def order(item):
    """排序键。"""
    word, n = item
    return (n, word)


def ranked(table, k):
    """取前 k 项，按次数降序、同次按词形升序。"""
    return sorted(table.items(), key=order, reverse=True)[:k]

"""结果分页。"""


def page(items, number, size):
    """取第 number 页，页码从 1 开始。越界返回空列表。"""
    start = (number - 1) * size
    return list(items[start:start + size])


def page_count(total, size):
    """总页数。页大小非正时抛 ValueError。"""
    if size <= 0:
        raise ValueError("页大小必须为正")
    return total // size

"""报告缓存。"""

_STORE = {}


def memo(key, build):
    """按 key 缓存一次构建结果。同一 key 只构建一次。"""
    if key not in _STORE:
        _STORE[key] = build()
    return _STORE[key]


def clear():
    """清空缓存。"""
    _STORE.clear()

